import { revalidateTag } from 'next/cache';
import { getCachedProducts } from '@/lib/catalog';

export default async function AdminCatalogPage() {
  const products = await getCachedProducts();

  async function syncCatalog() {
    'use server';

    // Trigger background revalidation without blocking
    revalidateTag('products');
  }

  return (
    <div style={{ padding: '2rem', maxWidth: '1200px', margin: '0 auto' }}>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '2rem' }}>
        <h1 style={{ fontSize: '2rem', fontWeight: 'bold' }}>Product Catalog</h1>

        <form action={syncCatalog}>
          <button
            type="submit"
            style={{
              padding: '0.5rem 1rem',
              backgroundColor: '#0070f3',
              color: 'white',
              border: 'none',
              borderRadius: '0.375rem',
              cursor: 'pointer',
              fontWeight: '500'
            }}
          >
            Sync latest catalog
          </button>
        </form>
      </div>

      <div style={{ border: '1px solid #eaeaea', borderRadius: '0.5rem', overflow: 'hidden' }}>
        <table style={{ width: '100%', borderCollapse: 'collapse' }}>
          <thead style={{ backgroundColor: '#fafafa' }}>
            <tr>
              <th style={{ padding: '1rem', textAlign: 'left', fontWeight: '600' }}>ID</th>
              <th style={{ padding: '1rem', textAlign: 'left', fontWeight: '600' }}>Product Name</th>
              <th style={{ padding: '1rem', textAlign: 'right', fontWeight: '600' }}>Price</th>
            </tr>
          </thead>
          <tbody>
            {products.map((product, index) => (
              <tr
                key={product.id}
                style={{
                  borderTop: index > 0 ? '1px solid #eaeaea' : 'none'
                }}
              >
                <td style={{ padding: '1rem' }}>{product.id}</td>
                <td style={{ padding: '1rem' }}>{product.name}</td>
                <td style={{ padding: '1rem', textAlign: 'right' }}>
                  ${product.price.toLocaleString()}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      <p style={{ marginTop: '1rem', color: '#666', fontSize: '0.875rem' }}>
        Total products: {products.length}
      </p>
    </div>
  );
}

